from pathlib import Path
import json,hashlib
from PIL import Image,ImageDraw
P=Path(__file__).resolve().parent;R=P.parents[1];O=R/'output/bill-death-ground-south-lateral-paired-station-v1'
records=json.loads((O/'contacts.json').read_text())['records'];hashes={}
for contact,crop in [('counter',(495,520,640,665)),('aisle',(385,300,530,445))]:
 board=Image.new('RGB',(435,330),(34,52,62));draw=ImageDraw.Draw(board)
 for row,gear in enumerate([False,True]):
  for col,phase in enumerate(['before-kneel','entry','terminal']):
   item=next(r for r in records if r['contact']==contact and r['direction']=='south' and r['gear']==gear and r['phase']==phase)
   f=O/item['screenshot'];board.paste(Image.open(f).convert('RGB').crop(crop),(col*145,row*165+20));draw.text((col*145+2,row*165+2),('helmet ' if gear else 'bare ')+phase,fill='white')
 board.save(P/f'station-{contact}-review.png')
for f in O.glob('*.png'):hashes[f.name]=hashlib.sha256(f.read_bytes()).hexdigest()
(P/'station-review.json').write_text(json.dumps({'status':'lateral_terminal_counter_projection_clear_candidate','captureBindings':hashes,'scope':'south bare/equipped kneel-entry-terminal crops; forced fixture heading, not normal chosen motion; finer joins and other physical clearance pending'},indent=2)+'\n',encoding='utf-8')
(P/'station-review.html').write_text('''<!doctype html><meta charset="utf-8"><title>Bill lateral collapse room review</title><style>body{background:#152027;color:#e6eff1;font:16px system-ui;margin:24px}img{max-width:100%}p{max-width:85ch}a{color:#80d4df}</style><h1>Bill — south lateral collapse at the counter</h1><p>Native-scale room crops: previous kneel, selected lowered entry and held terminal. Bare and shared-helmet versions. Terminal projected counter overlap is clear at this audited contact. Fine pose joins and wider physical clearance remain under review; no normal runtime choice yet.</p><h2>Counter</h2><img src="station-counter-review.png"><h2>Aisle</h2><img src="station-aisle-review.png"><p><a href="index.html">Play the candidate beside its idle</a></p>''',encoding='utf-8')
(P/'index.html').write_text('''<!doctype html><meta charset="utf-8"><title>Bill south lateral collapse candidate</title><style>body{font:16px system-ui;background:#152027;color:#e6eff1;margin:24px}button,select{font:inherit;padding:6px}p{max-width:85ch}input{width:350px}a{color:#80d4df}</style><h1>Bill — south lateral collapse</h1><p>Finite two-second candidate, exact accepted idle, shared rear helmet. Counter terminal tested in the actual room. Contact-aware normal selection and finer joins remain unfinished.</p><select id="gear"><option value="0">Bare</option><option value="1">Shared helmet</option></select><select id="size"><option>148</option><option>82</option><option>54</option></select><button id="replay">Replay</button><input id="scrub" type="range" min="0" max="2000" value="0"><span id="stamp"></span><br><canvas id="view" width="720" height="420"></canvas><p><a href="station-review.html">Actual counter and aisle review</a></p><script>
const load=f=>new Promise((resolve,reject)=>{const im=new Image;im.onload=()=>resolve(im);im.onerror=reject;im.src=f});let t=0,last=performance.now(),playing=true;
replay.onclick=()=>{t=0;playing=true};scrub.oninput=()=>{t=Number(scrub.value);playing=false};
Promise.all(['manifest.json','../bill-death-ground-helmet-south-lateral-v1/manifest.json'].map(f=>fetch(f).then(r=>r.json()))).then(async manifests=>{const rows=await Promise.all(manifests.map((m,j)=>Promise.all(m.states[0].frameFiles.map(f=>load(j?'../bill-death-ground-helmet-south-lateral-v1/'+f:f)))));function draw(now){if(playing)t=Math.min(2000,t+now-last);last=now;scrub.value=t;stamp.textContent=(t/1000).toFixed(2)+' s';const j=Number(gear.value),images=rows[j],s=manifests[j].states[0];let elapsed=t,index=images.length-1;for(let i=0;i<images.length;i++){if(elapsed<s.frameDurationsMs[i]){index=i;break}elapsed-=s.frameDurationsMs[i]}const c=view.getContext('2d'),scale=Number(size.value)/148;c.fillStyle='#22343e';c.fillRect(0,0,720,420);c.fillStyle='#e6eff1';c.fillText('Lateral collapse candidate',130,35);c.fillText('Selected idle',460,35);c.drawImage(images[index],200-128*scale,330-224*scale,256*scale,256*scale);c.drawImage(images[0],520-128*scale,330-224*scale,256*scale,256*scale);requestAnimationFrame(draw)}requestAnimationFrame(draw)});
</script>''',encoding='utf-8')
print('Built hash-bound south paired room review and finite gear-selectable preview')
